<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue';
import {FileClock,RefreshCw,Search,Users,User,PanelTop,CheckCircle,Eye,LogIn,ClipboardList} from '@lucide/vue';
interface Event {id:number;timestamp:string;account:string;name:string;role:string;ip:string;path:string;method:string;status:number;kind:string;user_agent:string}
const items=ref<Event[]>([]),total=ref(0),page=ref(1),q=ref(''),kind=ref(''),auto=ref(true),error=ref(''),updated=ref(''),loading=ref(false);
const role=ref(''),result=ref(''),since=ref(''),until=ref('');
const stats=ref({today_views:0,online_sessions:0,online_accounts:0});let timer:ReturnType<typeof setTimeout>|undefined;let serial=0;let alive=true;
const roleLabel=(r:string)=>({guest:'未登录访客',student:'学生',teacher:'教师',admin:'管理员',super_admin:'超级管理员'}[r]||r);
const eventLabel=(k:string)=>({page_view:'浏览页面',login:'登录',operation:'操作请求'}[k]||k);
async function load(){const request=++serial;loading.value=true;try{
 const token=localStorage.getItem('medical_auth_token');const response=await fetch(`${import.meta.env.VITE_API_BASE_URL||''}/api/admin/access-audit?${new URLSearchParams({q:q.value,kind:kind.value,page:String(page.value),size:'30',role:role.value,result:result.value,...(since.value?{since:new Date(since.value).toISOString()}:{}),...(until.value?{until:new Date(until.value).toISOString()}:{} )})}`,{headers:token?{Authorization:`Bearer ${token}`}:{}});
 if(!response.ok){const p=await response.json().catch(()=>({}));throw new Error(p.detail||'访问审计读取失败');}
 const data=await response.json();if(request!==serial||!alive)return;items.value=data.items;total.value=data.total;stats.value=data;updated.value=new Date().toLocaleString('zh-CN',{hour12:false});error.value='';
 }catch(e){if(alive&&request===serial)error.value=(e as Error).message;}finally{if(alive&&request===serial)loading.value=false;}}
async function tick(){if(!alive)return;if(auto.value&&document.visibilityState==='visible'&&!loading.value)await load();if(alive)timer=setTimeout(tick,5000);}
onMounted(async()=>{await load();if(alive)timer=setTimeout(tick,5000);});onUnmounted(()=>{alive=false;++serial;if(timer)clearTimeout(timer);});
</script>
<template><section id="access-audit" class="access-audit surface-panel"><header><div><h2><FileClock :size="22"/>网站访问与操作审计</h2><p>查看谁在何时访问了哪些页面，自动更新访问及操作记录。</p></div><div><span class="live-indicator">● 实时监控中</span><label><input v-model="auto" type="checkbox"/>每 5 秒自动刷新</label><button :disabled="loading" @click="load"><RefreshCw :size="15"/>刷新</button></div></header><div class="access-stats"><span><i><PanelTop :size="25"/></i><div><small>今日页面访问</small><b>{{stats.today_views}}</b></div></span><span><i><Users :size="25"/></i><div><small>近 90 秒在线会话</small><b>{{stats.online_sessions}}</b></div></span><span><i><User :size="25"/></i><div><small>在线登录账号</small><b>{{stats.online_accounts}}</b></div></span><small v-if="updated">上次更新 {{updated}}</small></div><form @submit.prevent="page=1;load()"><label class="search"><Search :size="16"/><input v-model="q" placeholder="搜索账号、姓名、IP 或页面路径" aria-label="搜索访问记录"/></label><select v-model="kind" aria-label="审计类型" @change="page=1;load()"><option value="">全部记录</option><option value="page_view">浏览页面</option><option value="login">登录</option><option value="operation">操作请求</option></select><select v-model="role" aria-label="角色筛选" @change="page=1;load()"><option value="">全部角色</option><option value="guest">访客</option><option value="student">学生</option><option value="teacher">教师</option><option value="admin">管理员</option><option value="super_admin">超级管理员</option></select><select v-model="result" aria-label="结果筛选" @change="page=1;load()"><option value="">全部结果</option><option value="success">成功</option><option value="failure">失败</option></select><div class="time-range"><input v-model="since" type="datetime-local" aria-label="开始时间"/><span>—</span><input v-model="until" type="datetime-local" aria-label="结束时间"/></div><button class="query-button">查询</button></form><p v-if="error" role="alert" class="access-error">{{error}}，可点击刷新重试。</p><div class="access-table"><table><thead><tr><th>访问时间</th><th>账号 / 身份</th><th>IP 地址</th><th>事件</th><th>页面 / 接口</th><th>结果</th><th>浏览器信息</th></tr></thead><tbody><tr v-for="e in items" :key="e.id"><td>{{new Date(e.timestamp).toLocaleString('zh-CN',{hour12:false})}}</td><td><strong>{{e.name}}</strong><small>{{e.account||'未登录'}} · {{roleLabel(e.role)}}</small></td><td>{{e.ip||'未知'}}</td><td><span class="event-type"><Eye v-if="e.kind==='page_view'" :size="14"/><LogIn v-else-if="e.kind==='login'" :size="14"/><ClipboardList v-else :size="14"/>{{eventLabel(e.kind)}}</span></td><td class="access-path">{{e.method}} {{e.path}}</td><td><span class="result-tag" :class="{failed:e.status>=400}"><CheckCircle :size="13"/>{{e.status<400?'成功':'失败'}} {{e.status}}</span></td><td><span class="agent" :title="e.user_agent">{{e.user_agent||'未知'}}</span></td></tr></tbody></table><p v-if="!items.length" class="empty">{{loading?'正在读取访问记录…':'暂无匹配记录，新访问会自动显示在这里。'}}</p></div><footer><small>访客仅能识别会话与网络地址，IP 不等于真实身份。在线会话由可见页面心跳估算；页面路径不保留查询参数。</small><div><button :disabled="page===1||loading" @click="page--;load()">上一页</button><span>{{page}} / {{Math.max(1,Math.ceil(total/30))}} · {{total}} 条</span><button :disabled="page*30>=total||loading" @click="page++;load()">下一页</button></div></footer></section></template>
