dding:25px;color:#64748b}.access-audit footer{display:flex;justify-content:space-between;gap:18px;margin-top:15px;align-items:center}.access-audit footer>small{font-size:11px;line-height:1.8;color:#64748b;max-width:65ch}.access-audit footer>div{display:flex;align-items:center;gap:10px;white-space:nowrap;font-size:12px}@media(max-width:760px){.access-audit{padding:16px}.access-audit header,.access-audit footer{align-items:flex-start;flex-direction:column}.access-stats{gap:12px}.access-stats small{margin-left:0}}
.access-audit{margin:0;border:1px solid #e0eaff;border-radius:20px;padding:13px 20px 12px;background:linear-gradient(130deg,#fff,#f5f9ff);box-shadow:0 5px 14px #3066c30b}.access-audit header{gap:10px}.access-audit header>div:first-child{display:flex;align-items:center;gap:18px;min-width:0}.access-audit header h2{font-size:19px;font-weight:800;white-space:nowrap}.access-audit header h2>svg{color:#0055ff}.access-audit header p{margin:0;padding-left:18px;border-left:1px solid #e1eaff;font-size:11px;line-height:1.7}.access-audit header>div:last-child{flex-shrink:0;gap:15px;font-size:11px}.live-indicator{color:#078957;background:#e3f8ef;border-radius:20px;padding:4px 10px;font-size:10px;white-space:nowrap}.access-audit header label{white-space:nowrap;display:flex;align-items:center;gap:5px}.access-audit input[type=checkbox]{accent-color:#0055ff}.access-stats{margin:13px 0 12px;background:linear-gradient(110deg,#eef7ff,#e7f2ff);gap:0;padding:0;min-height:61px;border-radius:13px;align-items:center}.access-stats>span{display:flex;align-items:center;gap:16px;flex:1;padding:8px 24px;min-width:0;border-right:14px solid #fff}.access-stats>span>i{display:grid;place-items:center;width:40px;height:40px;background:#e2f2ff;border-radius:11px;color:#0055ff;flex-shrink:0}.access-stats>span small{display:block;font-size:12px;color:#4c6b95;white-space:nowrap}.access-stats b{display:block;font-size:27px;color:#0050ff;line-height:1.1;margin:3px 0 0}.access-stats>small{padding:0 16px;font-size:11px;white-space:nowrap;margin-left:auto}.access-audit form{gap:10px;margin:12px 0}.access-audit .search{padding:7px 10px;min-width:200px}.access-audit select{width:113px;font-size:11px;padding:7px 8px;height:36px;font-weight:600}.access-audit form button{height:36px}.access-audit .query-button{background:linear-gradient(110deg,#2b8bff,#0862fb);color:white;border:0;padding:8px 22px}.time-range{display:flex;align-items:center;gap:4px;border:1px solid #d7e4ff;border-radius:10px;background:white;padding:4px 8px}.time-range input{width:145px;min-width:0;font-size:10px;color:#557199;border:0;background:none;font-family:inherit;padding:3px}.time-range span{color:#7e99bf;font-size:12px}.access-table{max-height:250px}.access-table th{font-size:11px;font-weight:800;color:#102c5d;padding:9px 12px;background:#e4eeff}.access-table td{padding:7px 12px;font-size:11px;line-height:1.3;color:#15386d}.access-table td strong{font-weight:750}.access-table td small{font-size:10px;margin-top:3px}.event-type{display:flex;align-items:center;gap:8px;white-space:nowrap}.event-type>svg{color:#005bff}.result-tag{display:inline-flex;align-items:center;gap:5px;white-space:nowrap;border-radius:20px;background:#dff9ec;color:#058754;padding:3px 8px;font-size:11px}.result-tag.failed{background:#ffe6e6;color:#c42a22}.access-table .access-path{min-width:160px;max-width:310px}.agent{max-width:250px}.access-audit footer{margin-top:10px}.access-audit footer>small{font-size:10px}.access-audit footer button{padding:5px 9px;font-size:11px}.access-audit footer>div{font-size:10px}
